// Settings, in one place: every event passes through here.
// Landbright's machine API (the Landbright API credential holds the application's client credentials):
const LANDBRIGHT_URL = 'http://127.0.0.1:4401';
// Which bundles cost a seat, until Landbright marks it on the bundle's target (landbrightApp, proposed by Landbright):
// a bundle's name → the app key a Landledger contract names (Landledger → Contracts, landbrightApp).
const SEAT_APPS = { 'Linear (seat)': 'linear' };
// Settle Landbright's cost step from Landledger's decision. Off: Landbright has no external step yet (proposed:
// POST /api/v1/requests/:id/steps/:step/settle { outcome, reference }, scope steps:settle), so the flow only notes the
// decision on the Landbright request. Turn it on once Landbright ships the step, and set its position.
const SETTLE_IN_LANDBRIGHT = false;
const COST_STEP = 1;
return { ...$json, settings: { landbrightUrl: LANDBRIGHT_URL.replace(/\/+$/, ''), seatApps: SEAT_APPS, settleInLandbright: SETTLE_IN_LANDBRIGHT, costStep: COST_STEP } };

// Landbright's events arrive as a signed JWT (the event in jwtPayload.event: trust that, not the body); Landledger's
// through the Landledger Trigger. 0: an access request was made (raise the cost); 1: Landledger decided the cost;
// 2: Landbright decided the access, or a grant moved (apply or release the seat); 3: anything else.
const settings = $json.settings;
const e = $json.jwtPayload?.event;
if (e) {
  const type = String(e.type ?? '');
  const landbrightRequestId = type.startsWith('request.') ? (e.target?.id ?? null) : (e.data?.requestId ?? null);
  const route = !landbrightRequestId ? 3 : type === 'request.created' ? 0 : type === 'request.decided' || type.startsWith('grant.') ? 2 : 3;
  return { route, source: 'landbright', eventType: type, landbrightRequestId, settings };
}
if ($json.type === 'request.decided' && $json.kind === 'tool_or_seat') {
  return { route: 1, source: 'landledger', eventType: $json.type, requestId: $json.requestId, outcome: $json.outcome, settings };
}
return { route: 3, source: 'other', eventType: String($json.type ?? ''), settings };

